import type { Firestore, Transaction } from "firebase-admin/firestore";
import type { PublicReleasePair } from "../../packages/content-core/src/public-release";
import type { PairAdmission, PairPublicationSource } from "./public-release-admission";
import type { PairSwitchInclusionAuthority } from "../../site/scripts/public-release-inclusion-switch";
export type RehearsalHoldPlan = Readonly<{ schemaVersion: 2; runId: string; operationId: string; pair: PublicReleasePair;
  targetPair: PublicReleasePair; expectedEpoch: number; source: PairPublicationSource; durationMs: number; releaseActionId: string; cancelActionId: string }>;
export type RehearsalHoldIntent = Readonly<{ schemaVersion: 2; kind: "rehearsal-terminal-hold"; plan: RehearsalHoldPlan;
  planDigest: string; createdAt: number; expiresAt: number }>;
export type RehearsalHoldBinding = Readonly<{ schemaVersion: 2; holdDigest: string; admissionDigest: string }>;
export type RehearsalHoldOutcome = Readonly<{ schemaVersion: 2; kind: "rehearsal-hold-outcome"; holdDigest: string;
  bindingDigest: string | null; outcome: "released" | "cancelled"; actionId: string; observedAt: number;
  evidence: null | { epoch: number; selectedPair: PairAdmission["pair"]; selectorDigest: string; executionDigest: string;
    inclusion: PairSwitchInclusionAuthority; canonicalProofDigest: string; coverageDigest: string } }>;
export type RehearsalHoldState = Readonly<{ intent: RehearsalHoldIntent; binding: RehearsalHoldBinding | null; outcome: RehearsalHoldOutcome | null;
  observedAt: number; status: "reserved" | "held" | "expired" | "released" | "cancelled" }>;
export const HOLD_MS_LIMIT: number;
export const HOLDS: string;
export function path(operationId: string): string;
export function parsePlan(raw: unknown): RehearsalHoldPlan;
export function parseIntent(raw: unknown): RehearsalHoldIntent;
export function parseOutcome(raw: unknown, intent: RehearsalHoldIntent, binding: RehearsalHoldBinding | null): RehearsalHoldOutcome;
type TransactionInput = { firestore: Firestore; transaction: Transaction; pair: PublicReleasePair; accepted: PairAdmission };
export function stateInTransaction(input: TransactionInput): Promise<RehearsalHoldState | null>;
export function assertNotHeldInTransaction(input: TransactionInput): Promise<RehearsalHoldState | null>;
export function prepareAdmissionInTransaction(input: TransactionInput): Promise<() => void>;
export function reserveRehearsalPublicationHold(input: { firestore: Firestore; plan: RehearsalHoldPlan; enabled?: boolean }): Promise<RehearsalHoldIntent>;
export function readRehearsalPublicationHold(input: { firestore: Firestore; plan: RehearsalHoldPlan }): Promise<RehearsalHoldState | null>;
export function cancelRehearsalPublicationHold(input: { firestore: Firestore; plan: RehearsalHoldPlan; enabled?: boolean;
  holdDigest: string; actionId: string }): Promise<RehearsalHoldOutcome>;
export class RehearsalPublicationHeldError extends Error {}
